    {"id":"FSD-C089","srNo":89,"marks":5,"topic":"HTML Tables","question":"Give the code to print given table.","solution":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Average Height and Weight Table</title>\n</head>\n<body>\n  <table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" align=\"center\">\n    <tr>\n      <td rowspan=\"2\"></td>\n      <th colspan=\"2\">average</th>\n      <th rowspan=\"2\">other<br>category</th>\n    </tr>\n    <tr>\n      <th>height</th>\n      <th>weight</th>\n    </tr>\n    <tr align=\"center\">\n      <th>males</th>\n      <td>1.9</td>\n      <td>0.003</td>\n      <td>yyy</td>\n    </tr>\n    <tr align=\"center\">\n      <th>females</th>\n      <td>1.7</td>\n      <td>0.002</td>\n      <td>xxx</td>\n    </tr>\n  </table>\n</body>\n</html>","imageUrl":"https://fsd-1-delta.vercel.app/assets/questions/u2/q89.png","imageAlt":"Average height, weight and other category table for males and females"},
    {"id":"FSD-C090","srNo":90,"marks":5,"topic":"HTML Tables","question":"Write an HTML script to code given table:","solution":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Table</title>\n</head>\n<body>\n  <center><h3>Table</h3></center>\n  <table border=\"2\" cellpadding=\"15\" cellspacing=\"2\" align=\"center\" width=\"90%\">\n    <tr align=\"center\">\n      <td rowspan=\"2\" bgcolor=\"yellow\"><b>A</b></td>\n      <td bgcolor=\"lightgreen\"><b>B</b></td>\n      <td rowspan=\"3\" bgcolor=\"yellow\"><b>D</b></td>\n      <td colspan=\"2\" bgcolor=\"pink\"><b>E</b></td>\n      <td bgcolor=\"lightblue\"><b>F</b></td>\n    </tr>\n    <tr align=\"center\">\n      <td bgcolor=\"lightblue\"><b>C</b></td>\n      <td bgcolor=\"lightgreen\"><b>G</b></td>\n      <td bgcolor=\"pink\"><b>H</b></td>\n      <td bgcolor=\"lightblue\"><b>I</b></td>\n    </tr>\n    <tr align=\"center\">\n      <td colspan=\"2\" bgcolor=\"pink\"><b>J</b></td>\n      <td colspan=\"2\" bgcolor=\"lightgreen\"><b>K</b></td>\n      <td bgcolor=\"yellow\"><b>L</b></td>\n    </tr>\n    <tr align=\"center\">\n      <td colspan=\"2\" bgcolor=\"lightgreen\"><b>M</b></td>\n      <td bgcolor=\"pink\"><b>N</b></td>\n      <td colspan=\"3\" bgcolor=\"lightblue\"><b>O</b></td>\n    </tr>\n  </table>\n</body>\n</html>","imageUrl":"https://fsd-1-delta.vercel.app/assets/questions/u2/q90.png","imageAlt":"Complex colored table with lettered cells"},
    {"id":"FSD-C091","srNo":91,"marks":5,"topic":"HTML Tables","question":"Draw table as asked.","solution":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Purchased Equipments (June, 2006)</title>\n</head>\n<body>\n  <table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" align=\"center\" width=\"90%\">\n    <caption><strong>Purchased Equipments (June, 2006)</strong></caption>\n    <tr>\n      <th>Item Name</th>\n      <th>Item Picture</th>\n      <th>Item Description</th>\n      <th>Price</th>\n    </tr>\n    <tr>\n      <td rowspan=\"2\" align=\"center\">1</td>\n      <td rowspan=\"2\" align=\"center\"><img src=\"computer.jpg\" alt=\"IBM Clone\" width=\"80\"/></td>\n      <td>IBM Clone Computer</td>\n      <td align=\"right\">$400.00</td>\n    </tr>\n    <tr>\n      <td>Shipping Handling, Installation, etc</td>\n      <td align=\"right\">$20.00</td>\n    </tr>\n    <tr>\n      <td rowspan=\"2\" align=\"center\">2</td>\n      <td rowspan=\"2\" align=\"center\"><img src=\"ram.jpg\" alt=\"1GB RAM\" width=\"80\"/></td>\n      <td>1GB RAM Module for Computer</td>\n      <td align=\"right\">$50.00</td>\n    </tr>\n    <tr>\n      <td>Shipping Handling, Installation, etc</td>\n      <td align=\"right\">$14.00</td>\n    </tr>\n  </table>\n</body>\n</html>","imageUrl":"https://fsd-1-delta.vercel.app/assets/questions/u2/q91.png","imageAlt":"Purchased Equipments (June, 2006) invoice table"},
    {"id":"FSD-C106","srNo":106,"marks":5,"topic":"HTML Tables","question":"Write an HTML script to code following table:","solution":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Time Table</title>\n</head>\n<body>\n  <center><h2>Time Table</h2></center>\n  <table border=\"1\" cellpadding=\"12\" cellspacing=\"0\" align=\"center\" width=\"80%\">\n    <tr align=\"center\">\n      <th colspan=\"3\">Header 1</th>\n      <th colspan=\"2\">Header 2</th>\n    </tr>\n    <tr align=\"center\">\n      <td rowspan=\"3\"><b>Food Items</b></td>\n      <td>Pizza</td>\n      <td>Burger</td>\n      <td colspan=\"2\">Fries</td>\n    </tr>\n    <tr align=\"center\">\n      <td>Maggie</td>\n      <td>Pasta</td>\n      <td>Rolls</td>\n      <td rowspan=\"2\">Sticks</td>\n    </tr>\n    <tr align=\"center\">\n      <td colspan=\"2\">Grill</td>\n      <td>Non-Grill</td>\n    </tr>\n    <tr align=\"center\">\n      <td><b>Cold Drinks</b></td>\n      <td colspan=\"4\">Coca Cola</td>\n    </tr>\n    <tr align=\"center\">\n      <td colspan=\"5\"><b>Confirm Order</b></td>\n    </tr>\n  </table>\n</body>\n</html>","imageUrl":"https://fsd-1-delta.vercel.app/assets/questions/u2/q106.png","imageAlt":"Weekly Time Table layout"},
    {"id":"FSD-C107","srNo":107,"marks":5,"topic":"HTML Tables","question":"Write an HTML code to create the table as shown in the figure given alongside.","solution":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Product Catalog Table</title>\n</head>\n<body>\n  <table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" align=\"center\" width=\"85%\">\n    <tr align=\"center\">\n      <th>Category</th>\n      <th>Product</th>\n      <th>Details</th>\n      <th>Quantity</th>\n      <th>Price</th>\n    </tr>\n    <tr align=\"center\">\n      <td rowspan=\"3\">Electronics</td>\n      <td rowspan=\"2\">Laptop</td>\n      <td align=\"left\">\n        <ol type=\"A\" start=\"5\">\n          <li>Brand A\n            <ol type=\"I\" start=\"9\">\n              <li>Intel i5</li>\n              <li>8GB RAM</li>\n            </ol>\n          </li>\n          <li>Brand B\n            <ul type=\"circle\">\n              <li>Intel i7</li>\n              <li>16GB RAM</li>\n            </ul>\n          </li>\n        </ol>\n      </td>\n      <td>5</td>\n      <td>$500</td>\n    </tr>\n    <tr align=\"center\">\n      <td>3</td>\n      <td>$600</td>\n      <td></td>\n    </tr>\n    <tr align=\"center\">\n      <td>Smartphone</td>\n      <td colspan=\"2\">Brand C</td>\n      <td>$300</td>\n    </tr>\n    <tr align=\"center\">\n      <td rowspan=\"2\">Accessories</td>\n      <td>Mouse &amp; Keyboard</td>\n      <td colspan=\"2\">Wireless</td>\n      <td>$50</td>\n    </tr>\n    <tr align=\"center\">\n      <td>Headphones</td>\n      <td colspan=\"2\">Over-ear, Noise-cancelling</td>\n      <td>$80</td>\n    </tr>\n  </table>\n</body>\n</html>","imageUrl":"https://fsd-1-delta.vercel.app/assets/questions/u2/q107.png","imageAlt":"Product category and price table for Electronics & Accessories"}
